// Writes .github/dependency-review.yml: the advisories in the libraries Minecraft itself ships, for every Minecraft
// version a test.<version> line in versions/*/gradle.properties names. The mod compiles and runs against those
// libraries, players' games ship them, and the mod bundles none of them, so Dependency review allows these and still
// checks everything the mod adds. Run it after adding a Minecraft version: node .github/minecraft-advisories.mjs
// Needs the GitHub CLI, signed in, for the advisory database.

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const root = path.join(import.meta.dirname, '..');
const versions = fs
  .readdirSync(path.join(root, 'versions'))
  .flatMap((line) =>
    [
      ...fs.readFileSync(path.join(root, 'versions', line, 'gradle.properties'), 'utf8').matchAll(/^test\.([^=]+)=/gm),
    ].map((m) => m[1]),
  )
  // Numeric order, so the file comes out the same on every filesystem.
  .sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));

const manifest = await (await fetch('https://piston-meta.mojang.com/mc/game/version_manifest_v2.json')).json();
const libraries = new Map(); // group:artifact@version -> Minecraft versions
for (const mc of versions) {
  const entry = manifest.versions.find((v) => v.id === mc);
  if (!entry) throw new Error(`Minecraft ${mc} isn't in Mojang's version manifest`);
  const meta = await (await fetch(entry.url)).json();
  for (const lib of meta.libraries) {
    const [group, artifact, version] = lib.name.split(':');
    const key = `${group}:${artifact}@${version}`;
    libraries.set(key, [...(libraries.get(key) ?? []), mc]);
  }
}

const advisories = new Map(); // GHSA id -> library versions it affects
for (const lib of [...libraries.keys()].sort()) {
  const found = JSON.parse(
    execFileSync(
      'gh',
      ['api', '-X', 'GET', '/advisories', '-f', 'ecosystem=maven', '-f', `affects=${lib}`, '-f', 'per_page=100'],
      {
        encoding: 'utf8',
      },
    ),
  );
  for (const a of found) advisories.set(a.ghsa_id, [...(advisories.get(a.ghsa_id) ?? []), lib]);
}

const lines = [...advisories.keys()].sort().map((id) => `  - ${id} # ${[...new Set(advisories.get(id))].join(', ')}`);
fs.writeFileSync(
  path.join(root, '.github', 'dependency-review.yml'),
  `# Generated by .github/minecraft-advisories.mjs from Minecraft ${versions.join(', ')}. Don't edit by hand.
# Advisories in libraries Minecraft ships with the game, which the mod compiles and runs against but doesn't bundle.
allow-ghsas:
${lines.join('\n')}
`,
);
process.stdout.write(
  `${libraries.size} library versions in ${versions.length} Minecraft versions, ${advisories.size} advisories\n`,
);
